/**
 * 院区标记的文字气泡要平移多少才不出屏。
 *
 * 气泡以标记为中心铺开（宽约 236px 的「中国电力科学研究院（武汉分院）」在 390px 手机上
 * 会顶到右边缘、还会压住右侧控制条）。这里用标准 tooltip 的做法：**保持居中，只在越界时
 * 平移到刚好落在安全区内**，而不是改成左/右对齐——对齐会把气泡整体挪半个身位，很容易
 * 从一边出屏换到另一边出屏（第一版就是这么翻车的：右缘越界 0.6px 就整体左移，左缘跑到 -17px）。
 *
 * 只看「标记中心 + 气泡宽度」这两个稳定量，不看气泡**当前**的位置，否则改完位移下一轮
 * 判断又会把位移算回去，来回抖动。
 */
export type MarkerLabelSide = 'center' | 'start' | 'end';

/** 两侧要留的余量：左边沿 8px，右边是控制条（42px 圆钮 + 贴边 12px）。 */
export const MARKER_LABEL_INSET = { start: 8, end: 52 } as const;

/** 居中时的左缘落在 [start, hostWidth - end - width] 里；越界就平移最小距离。 */
export function markerLabelShift(
  centerX: number,
  labelWidth: number,
  hostWidth: number,
  inset: { start: number; end: number } = MARKER_LABEL_INSET,
): number {
  const wanted = centerX - labelWidth / 2;
  const max = hostWidth - inset.end - labelWidth;
  if (max < inset.start) return inset.start - wanted; // 屏比气泡还窄：贴左，宁可右边被压
  return Math.min(Math.max(wanted, inset.start), max) - wanted;
}
