import type { z } from 'zod';
import type { basemapSchema } from './schema';

/**
 * 底图配置的类型出口与「可切换图层」的两个纯函数。
 *
 * 为什么单独一个文件：图层切换要同时被 `useMapEngine`（算瓦片）与 `MapPage`（画菜单）用到，
 * 而 `schema.ts` 只负责校验。这里放类型与套用逻辑，测试不用起 React。
 */
export type BasemapConfig = z.infer<typeof basemapSchema>;
export type TileBasemap = Extract<BasemapConfig, { kind: 'tiles' }>;
export type TileBasemapVariant = NonNullable<TileBasemap['variants']>[number];

/** 瓦片底图上可切换的图层；非瓦片底图或没配就是空数组。 */
export function tileVariants(basemap: BasemapConfig | undefined): TileBasemapVariant[] {
  return basemap?.kind === 'tiles' ? basemap.variants ?? [] : [];
}

/**
 * 把某个图层套到瓦片底图上：只换模板与署名，`bounds`/`minZoom`/`maxZoom`/`subdomains` 沿用原对象
 * ——天地图三种底图（影像 img_w / 矢量 vec_w / 地形 ter_w）是同一套 Web Mercator 网格与层级。
 *
 * 两个坑：
 * 1. 没有注记或备用模板的图层必须**显式清空**（赋 `undefined`），否则影像那套 `cia_w` 注记会
 *    留在矢量/地形上，出现「路名压在晕渲上」的错配；`fallbackTemplate` 同理（Esri 影像是影像专用）。
 * 2. 传入 `null`/无图层时原样返回，行为与不切换完全一致（`useMapEngine` 的 memo 依赖要稳）。
 */
export function applyTileVariant(
  basemap: BasemapConfig | undefined,
  variant: TileBasemapVariant | null | undefined,
): BasemapConfig | undefined {
  if (!basemap || basemap.kind !== 'tiles' || !variant) return basemap;
  return {
    ...basemap,
    urlTemplate: variant.urlTemplate,
    overlayTemplate: variant.overlayTemplate,
    fallbackTemplate: variant.fallbackTemplate,
    fallbackOverlayTemplate: variant.fallbackOverlayTemplate,
    attribution: variant.attribution ?? basemap.attribution,
  };
}
