import type { OrthoOverlayConfig } from '../../config/schema';
import { enuFromLngLat, type LngLat } from '../../shared/geo';

/**
 * 地图上那层**静态正射贴图**的摆放算术（纯函数，单测在 `orthoOverlay.test.ts`）。
 *
 * 为什么有这层：过去地图上的场地模型是实时三维画布（`SiteOverlay3D`），每次拖动地图都要重画
 * 910 万面、400+ draw call 的场景，只能靠 140ms 防抖"停下来再画"，手指下就是一顿一顿的。
 * 现在改成离线烘焙好的一张正射图：拖动地图只是移动一个 `<img>`，合成器就能完成，不再吃 GPU。
 *
 * 坐标系（与三维层同一套，别再发明第二套）：
 * - 锚点 = 模型局部原点的经纬（`siteModel.placement.anchor`）；
 * - `enuFromLngLat(锚点, 视野中心)` 给出视野中心相对锚点的东/北偏移（米）；
 * - 画布水平方向正好覆盖 `view.spanMeters` 米 → `米/像素 = spanMeters / view.width`；
 * - 画布 y 向下、北向上，所以北上角对应 `top`，east 向右。
 */
export interface MapOverlayView {
  center: LngLat;
  spanMeters: number;
  width: number;
  height: number;
}

/** 贴图在地图舞台上占的 CSS 像素矩形（`left`/`top` 相对舞台左上角，可正可负 = 移出视野）。 */
export interface OverlayRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

/**
 * 贴图应当画在哪儿。视野还不可用（跨度/尺寸为 0）时返回 `null`，调用方就别挂那层。
 */
export function orthoOverlayRect(
  ortho: OrthoOverlayConfig,
  anchor: LngLat,
  view: MapOverlayView,
): OverlayRect | null {
  if (!(view.spanMeters > 0) || !(view.width > 0) || !(view.height > 0)) return null;
  if (!(ortho.widthMeters > 0) || !(ortho.heightMeters > 0)) return null;

  const metersPerPixel = view.spanMeters / view.width;
  const enu = enuFromLngLat(anchor, view.center);
  // 贴图的西北角：中心往西半个图宽、往北半个图高。
  const west = ortho.centerEast - ortho.widthMeters / 2;
  const north = ortho.centerNorth + ortho.heightMeters / 2;

  return {
    left: view.width / 2 + (west - enu.east) / metersPerPixel,
    top: view.height / 2 - (north - enu.north) / metersPerPixel,
    width: ortho.widthMeters / metersPerPixel,
    height: ortho.heightMeters / metersPerPixel,
  };
}

/** 点（舞台 CSS 像素）落没落在这张图的矩形里——射线求交的廉价替身，先排除远处的点。 */
export function overlayRectContains(rect: OverlayRect | null, x: number, y: number): boolean {
  if (!rect) return false;
  return x >= rect.left && x <= rect.left + rect.width && y >= rect.top && y <= rect.top + rect.height;
}

/**
 * 模型旁那张提示卡（引导 / 「进入场地模型」）该摆在哪儿。
 *
 * 为什么要算：过去这两张卡是**深色气泡**，一张钉在屏幕右下（指着早已删掉的罗盘按钮）、
 * 一张跟着手指落点跑——都不在模型旁边，用户得自己把"这句话"和"那块模型"连起来。
 * 现在两张卡都贴到模型的屏幕矩形上：卡片浮在模型上沿（或下沿），卡内的小尖角指向模型中心。
 *
 * 只做水平与上下两个决定，纵向用 CSS 的 `top`/`bottom` 贴边而不是算高度——
 * 免去"先渲染再量高度再挪位"的循环。`card.height` 只在**决定上下**时当作估算值用。
 */
export interface CalloutPlacement {
  /** 卡片左缘的 CSS `left`（px，相对舞台）。 */
  left: number;
  /**
   * `above` = 卡片在模型上方（调用方把 `edge` 落到 CSS `bottom`）；
   * `below` = 卡片在模型下方（落到 CSS `top`）。
   */
  side: 'above' | 'below';
  /** 与 `side` 配套的定位值（px，相对舞台）。 */
  edge: number;
  /** 小尖角在卡片内的横向位置（px，相对卡片左缘），已夹在卡片圆角内侧。 */
  caretX: number;
}

const CALLOUT_CARET_INSET = 18;

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

export function modelCalloutPlacement(
  rect: OverlayRect,
  stage: { width: number; height: number },
  card: { width: number; height: number },
  gap = 12,
  margin = 10,
): CalloutPlacement | null {
  if (!(stage.width > 0) || !(stage.height > 0) || !(rect.width > 0) || !(rect.height > 0)) return null;
  const width = Math.min(card.width, stage.width - margin * 2);
  if (!(width > 0)) return null;

  const centerX = rect.left + rect.width / 2;
  const left = clamp(centerX - width / 2, margin, stage.width - width - margin);

  // 上面放得下就放上面（模型通常在地图中下部，上方更空）；上面放不下再看下面；
  // 两边都放不下时按"哪边空间大"选，宁可压住一点模型也不要飘到屏幕外。
  const above = rect.top - gap - card.height - margin;
  const below = stage.height - (rect.top + rect.height) - gap - card.height - margin;
  const side: CalloutPlacement['side'] = above >= 0
    ? 'above'
    : below >= 0
      ? 'below'
      : (rect.top >= stage.height - (rect.top + rect.height) ? 'above' : 'below');

  const edge = side === 'above' ? stage.height - (rect.top - gap) : rect.top + rect.height + gap;
  return {
    left,
    side,
    edge,
    caretX: clamp(centerX - left, CALLOUT_CARET_INSET, width - CALLOUT_CARET_INSET),
  };
}

/**
 * 点（舞台 CSS 像素）换算成贴图自己的像素坐标，用于查 alpha（空白处不该算"点在模型上"）。
 * 越界返回 `null`；`imageWidth` / `imageHeight` 传用来查表的那份位图尺寸即可（可以是缩略图）。
 */
export function overlayImagePoint(
  rect: OverlayRect | null,
  imageWidth: number,
  imageHeight: number,
  x: number,
  y: number,
): { x: number; y: number } | null {
  if (!rect || rect.width <= 0 || rect.height <= 0) return null;
  if (imageWidth <= 0 || imageHeight <= 0) return null;
  if (!overlayRectContains(rect, x, y)) return null;
  return {
    x: ((x - rect.left) / rect.width) * imageWidth,
    y: ((y - rect.top) / rect.height) * imageHeight,
  };
}
